  {foreach ui_l($v_days) as $v_d}
    {capture $c_9}
      {capture $c_3}
        {capture $c_1}
          {=ui_text(ui_get($v_d, ['title']))}
        {/capture}
        {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_1])|noescape}
        {capture $c_2}
