          {=ui_include('ui/label/label.latte', ['p' => ['Class' => 'flex items-center gap-2 rounded px-4 py-2 text-sm inset-ring inset-ring-border has-checked:bg-muted has-checked:inset-ring-foreground'], 'children' => $c_5])|noescape}
        {/foreach}
        {foreach ui_l(ui_get($v_d, ['closed'])) as $v_s}
          {capture $c_7}
            {=ui_include('ui/radio/radio.latte', ['p' => ['Name' => ui_s($v_name), 'Value' => ui_s(ui_tpl('{0} {1}', [ui_get($v_d, ['id']), $v_s])), 'Disabled' => true]])|noescape}
            {capture $c_6}
              {=ui_text($v_s)}
            {/capture}
            {=ui_include('ui/inline/inline.latte', ['p' => [], 'children' => $c_6])|noescape}
          {/capture}
          {=ui_include('ui/label/label.latte', ['p' => ['Class' => ui_s(ui_cnv(['flex items-center gap-2 rounded px-4 py-2 text-sm inset-ring inset-ring-border has-checked:bg-muted has-checked:inset-ring-foreground', 'text-muted-foreground line-through']))], 'children' => $c_7])|noescape}
        {/foreach}
      {/capture}
      {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'grid grid-cols-2 gap-2 sm:grid-cols-3'], 'children' => $c_8])|noescape}
    {/capture}
    {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Class' => ui_s((ui_t(ui_eq($v_item, 'card')) ? 'rounded bg-card inset-ring inset-ring-border p-4' : 'border-b border-border pb-4')), 'Attrs' => ui_attrs(['data-testid', 'day'])], 'children' => $c_9])|noescape}
